#!/usr/bin/env bash
#
# selftest.sh -- prove the judge can fail.
#
#   judge/grade.sh examples/good            must PASS
#   judge/grade.sh <each mutant>            must FAIL, at least one gate
#
# Prints the kill rate (mutants caught / mutants total) and exits non-zero if
# the known-good artifact does not pass, or the kill rate is under 90 %.
#
# Mutants are generated by judge/mutate.py from examples/good. Every mutant
# is a single-edit copy, so a mutant that survives grading is an equivalent
# mutation -- a real deviation the judge cannot see. All mutants here are
# meant to be caught by an oracle/byte-compare gate, so the kill rate is
# counted over all of them.

set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
DEMO="$(dirname "${HERE}")"
WORK="$(mktemp -d /tmp/mlr-self.XXXXXX)"
trap 'rm -rf "$WORK"' EXIT

PY="${PYTHON:-python3}"

echo "== selftest =========================================================="
echo "good artifact : ${DEMO}/examples/good"
echo "mutant source : ${HERE}/mutate.py (single-edit mutants)"
echo

# --------------------------------------------------------------------------
# 1. The known-good artifact must pass.  A judge that fails its own reference
#    is not a judge.
# --------------------------------------------------------------------------
echo "--- known-good -------------------------------------------------------"
bash "${HERE}/grade.sh" "${DEMO}/examples/good" \
    --seed 20261015 --json "${WORK}/good.json" > "${WORK}/good.log" 2>&1
GOOD_RC=$? || exit 1
GOOD_JSON="$(cat "${WORK}/good.json" 2>/dev/null)"

GOOD_PASSED="$(printf '%s' "$GOOD_JSON" | "$PY" -I -c \
    'import json,sys; d=json.load(sys.stdin); print("yes" if d.get("pass") else "no")' \
    2>/dev/null || echo "unreadable")"
GOOD_GATES="$(printf '%s' "$GOOD_JSON" | "$PY" -I -c \
    'import json,sys; d=json.load(sys.stdin); g=d.get("gates",{}); print("%d/%d" % (sum(1 for v in g.values() if v), len(g)))' \
    2>/dev/null || echo "?/?")"

if [ "$GOOD_RC" -eq 0 ] && [ "$GOOD_PASSED" = "yes" ]; then
    echo "PASS  known-good artifact (${GOOD_GATES} gates)  exit=${GOOD_RC}"
else
    echo "FAIL  known-good artifact (${GOOD_GATES} gates)  exit=${GOOD_RC}"
    echo "      the judge must pass its own reference; aborting"
    sed -n '1,30p' "${WORK}/good.log" >&2
    exit 1
fi
echo

# --------------------------------------------------------------------------
# 1b. Determinism: the same seed must give the same verdict, every time.
#     Everything allowed to differ (wall clock, elapsed time) lives under
#     the `timing` key.
# --------------------------------------------------------------------------
echo "--- determinism ------------------------------------------------------"
bash "${HERE}/grade.sh" "${DEMO}/examples/good" \
    --seed 20261015 --json "${WORK}/det1.json" > "${WORK}/det1.log" 2>&1
DET1_RC=$? || exit 1
bash "${HERE}/grade.sh" "${DEMO}/examples/good" \
    --seed 20261015 --json "${WORK}/det2.json" > "${WORK}/det2.log" 2>&1
DET2_RC=$? || exit 1
DET_SAME="$( "$PY" -I - "${WORK}/det1.json" "${WORK}/det2.json" <<'PYDET'
import json, sys
try:
    a = json.load(open(sys.argv[1])); b = json.load(open(sys.argv[2]))
except Exception:
    print("unreadable"); sys.exit(0)
a.pop("timing", None); b.pop("timing", None)
print("identical" if a == b else "DIFFERENT")
PYDET
)"
if [ "$DET1_RC" -eq 0 ] && [ "$DET2_RC" -eq 0 ] && [ "$DET_SAME" = "identical" ]; then
    echo "PASS  two same-seed runs give identical verdict JSON (minus timing)"
else
    echo "FAIL  determinism check: exits ${DET1_RC}/${DET2_RC}, verdicts ${DET_SAME}"
    exit 1
fi
echo

# --------------------------------------------------------------------------
# 2. Every mutant must fail at least one gate.
# --------------------------------------------------------------------------
MUTDIR="${WORK}/mutants"
"$PY" -I "${HERE}/mutate.py" "${DEMO}/examples/good" "$MUTDIR" > /dev/null

NAMES=()
while IFS= read -r name; do
    NAMES+=("$name")
done < <(ls -1 "$MUTDIR" | sort)

echo "--- known-bad mutants -----------------------------------------------"
printf '%-32s %-5s %-12s %s\n' "MUTANT" "EXIT" "KILL CLASS" "GATES FAILED"

KILLED=0
TOTAL=${#NAMES[@]}
for name in "${NAMES[@]}"; do
    OUT="${WORK}/${name}.json"
    bash "${HERE}/grade.sh" "${MUTDIR}/${name}" \
        --seed 20261015 --json "$OUT" > "${WORK}/${name}.log" 2>&1
    RC=$? || exit 1

    # Emit: "<gate> (<detail>); ..." for every failed gate, or NONE.
    FAILED_GATES="$(printf '%s' "$(cat "$OUT" 2>/dev/null)" | "$PY" -I -c \
        'import json,sys
try:
    d = json.load(sys.stdin)
except Exception:
    print("<no verdict JSON>"); sys.exit(0)
bad = [k for k, v in d.get("gates", {}).items() if not v]
detail = "; ".join("%s (%s)" % (k, f[:110]) for k, f in
                    zip(bad, [x for x in d.get("failures", []) if x.split(" ")[0].rstrip(":") in bad])) if bad else "NONE -- judge passed a broken artifact"
print(detail)' 2>/dev/null || echo "<unreadable>")"

    if [ "$RC" -ne 0 ]; then
        KILLED=$((KILLED + 1))
        CLASS="killed"
    else
        CLASS="SURVIVED"
    fi
    printf '%-32s %-5s %-12s %s\n' "$name" "$RC" "$CLASS" "$FAILED_GATES"
done

echo
if [ "$TOTAL" -eq 0 ]; then
    echo "SELFTEST FAILED: no mutants were generated"
    exit 1
fi
KILL_RATE="$( "$PY" -I -c "print(int(100*$KILLED/$TOTAL + 0.5))")"

echo "== summary ==========================================================="
echo "known-good            : PASS (${GOOD_GATES} gates)"
echo "mutants killed        : ${KILLED}/${TOTAL}"
echo "kill rate             : ${KILL_RATE} %"
echo

if [ "$KILL_RATE" -lt 90 ]; then
    echo "SELFTEST FAILED: kill rate ${KILL_RATE} % is below the 90 % floor"
    exit 1
fi

echo "SELFTEST PASSED: judge passes the good artifact and kills ${KILL_RATE}% of mutants"
exit 0
